verifier_source:
# Standalone deterministic verifier. Python 3, NO imports, NO filesystem, NO network, NO print. Entry point: verify(witness) — RAISES AssertionError on any failed check, returns True on full PASS. Fail-closed. Exact integer arithmetic only.
# Repair note: previous version computed the threshold e(n,2) with a vacuous-truth bug (for m<3 the universal condition holds vacuously, giving e_val=0). Fixed: the threshold is computed only over m>=3 and required to hold for ALL m in [e_val, C(n,2)] (monotone window), and cross-checked as max_counterexample + 1.

def _combinations(iterable, r):
    pool = tuple(iterable)
    if r > len(pool):
        return
    indices = list(range(r))
    yield tuple(pool[i] for i in indices)
    while True:
        for i in reversed(range(r)):
            if indices[i] != i + len(pool) - r:
                break
        else:
            return
        indices[i] += 1
        for j in range(i+1, r):
            indices[j] = indices[j-1] + 1
        yield tuple(pool[i] for i in indices)

def _pairs(t):
    a, b, c = t
    return [(a, b), (a, c), (b, c)]

def _triangles(N, edges):
    S = set(edges)
    tri = []
    for i in range(N):
        for j in range(i+1, N):
            for k in range(j+1, N):
                if (i, j) in S and (i, k) in S and (j, k) in S:
                    tri.append((i, j, k))
    return tri

def _counts(N, edges, tri):
    S = set(edges)
    cnts = {}
    for e in S:
        c = 0
        for t in tri:
            if e in _pairs(t):
                c += 1
        cnts[e] = c
    return cnts

def verify(witness):
    n = witness['n']
    trips = [tuple(t) for t in witness['packing_triples']]
    claimed_max = witness['claimed_max_counterexample_edges']
    claimed_e = witness['claimed_e6_2']

    # 1. packing validity: valid triples, pairwise edge-disjoint
    assert n >= 3
    assert len(trips) == 4
    seen = set()
    for t in trips:
        assert len(t) == 3
        assert all(isinstance(v, int) and 0 <= v < n for v in t)
        assert len(set(t)) == 3
        for p in _pairs(t):
            assert p not in seen
            seen.add(p)
    assert len(seen) == 3 * len(trips)
    assert 3 * len(trips) == claimed_max

    allE = [(i, j) for i in range(n) for j in range(i+1, n)]
    total = len(allE)

    # 2. exhaustive: max edges of a graph on n vertices with every edge in EXACTLY one triangle
    best = -1
    for m in range(total, 2, -1):
        found = False
        for combo in _combinations(allE, m):
            cnts = _counts(n, combo, _triangles(n, combo))
            if all(v == 1 for v in cnts.values()):
                found = True
                break
        if found:
            best = m
            break
    assert best == claimed_max

    # 3. exhaustive threshold: e(n,2) = min m >= 3 such that EVERY m-edge graph with all
    #    edges in >=1 triangle has an edge in >=2 triangles, AND this holds for every
    #    m' in [m, total] (no vacuous small-m artifact)
    e_val = -1
    for m in range(3, total + 1):
        ok = True
        for mp in range(m, total + 1):
            for combo in _combinations(allE, mp):
                cnts = _counts(n, combo, _triangles(n, combo))
                if all(v >= 1 for v in cnts.values()) and not any(v >= 2 for v in cnts.values()):
                    ok = False
                    break
            if not ok:
                break
        if ok:
            e_val = m
            break
    assert e_val == claimed_e
    assert e_val == best + 1

    return True

_WITNESS = {
    'n': 6,
    'packing_triples': [[0, 1, 2], [0, 3, 4], [1, 3, 5], [2, 4, 5]],
    'claimed_max_counterexample_edges': 12,
    'claimed_e6_2': 13
}

verify(_WITNESS)
